def _swap(text, heading, old, new, n):
    if text.count(heading) != 1:
        raise SystemExit("REFUSED: %s's heading is not there once; nothing written" % n)
    h = text.find(heading)
    s = text.rindex("\n\n", 0, h) + 2
    if text[s:h] != old:
        raise SystemExit("REFUSED: %s's status block is not the one this was written against; nothing written" % n)
    text = text[:s] + new + text[h:]
    if text.count(new + heading) != 1:
        raise SystemExit("REFUSED: %s's status no longer adjoins its heading; nothing written" % n)
    return text


def main():
    raw = RM.read_bytes()
    if b"\r\n" in raw:
        raise SystemExit("REFUSED: the roadmap is LF and CRLF was found; nothing written")
    text = raw.decode("utf-8")
    if STATUS_44_NEW[:80] in text or BODY_44_ADD[:80] in text:
        raise SystemExit("REFUSED: already applied; nothing written")
    text = _swap(text, HEADING_44, STATUS_44_OLD, STATUS_44_NEW, "44")
    if text.count(BODY_44_LAST) != 1:
        raise SystemExit("REFUSED: 44's last paragraph is not there once; nothing written")
    b = text.index(BODY_44_LAST) + len(BODY_44_LAST)
    if not text.startswith("\n\n*STATUS: ", b) or text.find("\n\n**45. ", b) < 0:
        raise SystemExit("REFUSED: 44's last paragraph is not where 44 ends; nothing written")
    text = text[:b] + BODY_44_ADD + text[b:]
    text = _swap(text, HEADING_280, STATUS_280_OLD, STATUS_280_NEW, "280")
    RM.write_bytes(text.encode("utf-8"))
    print("roadmap 44: NARROWED, the earlier status kept, a body paragraph added; 280's status updated, its earlier "
          "kept; now roadmap_status.py --write / --check")
    return 0


if __name__ == "__main__":
    sys.exit(main())
